import torch
import torch.nn.functional as f
z,v,h,w,b,u,c=[(w-71).reshape(s)*t for w,(s,t) in zip(torch.tensor([*P]).split([10,216,480,72,8,192,8]),[(10,32.493),((8,3,9),.079368),((10,48),1.),((8,1,3,3),1.),(8,.15962),((8,8,3),.0407925),(8,.62967)])]
k=(u@v).reshape(8,8,3,3)
def logits(x):
 x=f.conv2d(x,w,b,1,1).relu()
 for i in 0,0:
  for i in 0,0:x=(x+f.conv2d(x,k,c,1,1)).relu()
  x=f.max_pool2d(x,2)
 return f.linear(f.avg_pool2d(x,(3,4),(2,3)).reshape(-1,48),h,z)
def predict(x):return sum(logits(x.roll((i,j),(2,3))) for i in range(-2,3) for j in range(-2,3)).argmax(1)
